#include <string>
#include <unordered_set>

class Solution {
public:
    int distinctEchoSubstrings(std::string text) {
        int n = text.size();
        std::unordered_set<std::string> res;
        for (int len = 1; len <= n / 2; ++len) {
            for (int i = 0; i <= n - 2 * len; ++i) {
                std::string first = text.substr(i, len);
                std::string second = text.substr(i + len, len);
                if (first == second) {
                    res.insert(first);
                }
            }
        }
        return res.size();
    }
};

import java.util.*;

class Solution {
    public int distinctEchoSubstrings(String text) {
        int n = text.length();
        Set<String> res = new HashSet<>();
        for (int len = 1; len <= n / 2; len++) {
            for (int i = 0; i <= n - 2 * len; i++) {
                String first = text.substring(i, i + len);
                String second = text.substring(i + len, i + 2 * len);
                if (first.equals(second)) {
                    res.add(first);
                }
            }
        }
        return res.size();
    }
}

var distinctEchoSubstrings = function(text) {
    const n = text.length;
    const res = new Set();
    for (let len = 1; len <= Math.floor(n / 2); len++) {
        for (let i = 0; i <= n - 2 * len; i++) {
            const first = text.substring(i, i + len);
            const second = text.substring(i + len, i + 2 * len);
            if (first === second) {
                res.add(first);
            }
        }
    }
    return res.size;
};
